def _replace(source, target):
    conn = op.get_bind()
    for language in ("sv", "en", "nb"):
        conn.execute(sa.text(
            f"UPDATE prompt_fields SET default_{language} = :new "
            f"WHERE key = :key AND default_{language} = :old"
        ), {"key": _KEY, "old": source[language], "new": target[language]})


def upgrade():
    _replace(_OLD, _NEW)


def downgrade():
    _replace(_NEW, _OLD)
